export function webTotal(items, couponCents) {
  const subtotal = items.reduce((sum, x) => sum + x.unitPriceCents * x.quantity, 0);
  const discount = Math.min(couponCents, subtotal);
  return subtotal - discount;
}

export function partnerTotal(items, tierRate) {
  const subtotal = items.reduce((sum, x) => sum + x.unitPriceCents * x.quantity, 0);
  const discount = Math.floor(subtotal * tierRate);
  return subtotal - discount;
}

export function phoneTotal(items, manualCents) {
  const subtotal = items.reduce((sum, x) => sum + x.unitPriceCents * x.quantity, 0);
  const discount = Math.min(manualCents, 5000, subtotal);
  return subtotal - discount;
}
